import { Controller, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 제출 대상은 귀속 시작일이 제출 연도에 속한 지급명세서(PAYMENT_STATEMENT)다.
const TARGET_DOCUMENT_TYPE = 'PAYMENT_STATEMENT';
// 가정: 소득 구분 값은 income_certificate.certificate_category와 같은 값으로 집계한다.
// 가정: 전산매체 파일명 형식은 PAYMENT_STATEMENT_연도_소득구분_신고서ID.txt 로 정한다.

@Controller('api/v1')
export class FnSfr02309Controller {
  @Post('/tax-filings/submission-summaries')
  @HttpCode(200)
  async createSubmissionSummary(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const submissionYear = data['submissionYear'];
    const incomeCategory = data['incomeCategory'];
    if (typeof submissionYear !== 'string' || !/^\d{4}$/.test(submissionYear)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '제출 대상 연도는 4자리 숫자로 입력해 주세요.');
    }
    if (typeof incomeCategory !== 'string' || incomeCategory.trim() === '' || incomeCategory.length > 30) {
      throw new ApiError(400, 'VALIDATION_FAILED', '소득 구분을 30자 이내로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const sums = await db.query(
        `SELECT COUNT(*) AS "count",
                COALESCE(SUM(total_payment_amount), 0) AS "total"
           FROM income_certificate
          WHERE certificate_category = :category
            AND document_type = :documentType
            AND EXTRACT(YEAR FROM period_start) = CAST(:year AS integer)`,
        { category: incomeCategory, documentType: TARGET_DOCUMENT_TYPE, year: submissionYear },
      );
      if (!sums[0] || Number(sums[0].count) === 0) {
        throw new ApiError(404, 'PAYMENT_STATEMENT_NOT_FOUND', '제출 대상 지급명세서 데이터가 없습니다.');
      }
      const rows = await db.query(
        `INSERT INTO tax_filing (filing_type, submission_year, income_category, filing_status, total_amount, created_at, updated_at)
         VALUES ('SUBMISSION_SUMMARY', :year, :category, 'DRAFT', CAST(:total AS numeric), now(), now())
         RETURNING tax_filing_id AS "taxFilingId", total_amount AS "totalAmount"`,
        { year: submissionYear, category: incomeCategory, total: sums[0].total },
      );
      return rows[0];
    });
  }

  @Post('/tax-filings/:taxFilingId/generate-media')
  @HttpCode(200)
  async generatePaymentMediaFile(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const taxFilingId = req.params['taxFilingId'];
    if (!/^\d+$/.test(taxFilingId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '세무 신고서 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const filings = await db.query(
        `SELECT tax_filing_id AS "taxFilingId",
                submission_year AS "submissionYear",
                income_category AS "incomeCategory",
                total_amount AS "totalAmount"
           FROM tax_filing
          WHERE tax_filing_id = CAST(:id AS bigint)
            AND filing_type = 'SUBMISSION_SUMMARY'`,
        { id: taxFilingId },
      );
      if (filings.length === 0) {
        throw new ApiError(404, 'TAX_FILING_NOT_FOUND', '제출집계표를 찾을 수 없습니다.');
      }
      const filing = filings[0];
      if (!filing.submissionYear || !filing.incomeCategory || filing.totalAmount === null) {
        throw new ApiError(422, 'MEDIA_SPEC_VALIDATION_FAILED', '제출집계표에 연도, 소득 구분 또는 집계 금액이 없어 국세청 제출 규격에 맞지 않습니다.');
      }
      // 가정: 규격 검증은 대상 지급명세서마다 총지급액·원천징수세액·주민등록번호가 모두 있는지 확인한다.
      const checked = await db.query(
        `SELECT COUNT(*) AS "count",
                COALESCE(SUM(CASE WHEN total_payment_amount IS NULL
                                   OR withheld_tax_amount IS NULL
                                   OR resident_number_enc IS NULL THEN 1 ELSE 0 END), 0) AS "invalid"
           FROM income_certificate
          WHERE certificate_category = :category
            AND document_type = :documentType
            AND EXTRACT(YEAR FROM period_start) = CAST(:year AS integer)`,
        { category: filing.incomeCategory, documentType: TARGET_DOCUMENT_TYPE, year: filing.submissionYear },
      );
      if (!checked[0] || Number(checked[0].count) === 0) {
        throw new ApiError(422, 'MEDIA_SPEC_VALIDATION_FAILED', '전산매체로 만들 지급명세서 데이터가 없어 국세청 제출 규격에 맞지 않습니다.');
      }
      if (Number(checked[0].invalid) > 0) {
        throw new ApiError(422, 'MEDIA_SPEC_VALIDATION_FAILED', '필수 항목이 비어 있는 지급명세서가 ' + Number(checked[0].invalid) + '건 있어 파일 생성을 중단했습니다.');
      }
      const fileName = 'PAYMENT_STATEMENT_' + filing.submissionYear + '_' + filing.incomeCategory + '_' + filing.taxFilingId + '.txt';
      return { fileName };
    });
  }
}

