import { useState } from 'react';
import { call, Band, DataTable, Drawer, Form, Field, TextInput, Select, Num } from '../kit';
import type { PageProps } from '../kit';

type Summary = {
  taxFilingId: number;
  submissionYear: string;
  incomeCategory: string;
  totalAmount: number;
  fileName: string;
};

const CATEGORY_OPTIONS: [string, string][] = [
  ['DAILY_WAGE', '일용근로'],
  ['RETIREMENT_INCOME', '퇴직소득'],
  ['EARNED_INCOME', '근로소득'],
];

function categoryName(value: string): string {
  const found = CATEGORY_OPTIONS.find((o) => o[0] === value);
  return found ? found[1] : value;
}

export default function FnSfr02309Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Summary[]>([]);
  const [creating, setCreating] = useState(false);
  const [target, setTarget] = useState<Summary | null>(null);
  const [year, setYear] = useState('');
  const [category, setCategory] = useState('');

  const create = async () => {
    if (!/^\d{4}$/.test(year)) {
      throw new Error('제출 대상 연도를 4자리 숫자로 입력해 주세요.');
    }
    if (!category) {
      throw new Error('소득 구분을 선택해 주세요.');
    }
    const res = await call<{ taxFilingId: number; totalAmount: number }>(
      'POST',
      '/tax-filings/submission-summaries',
      role,
      { submissionYear: year, incomeCategory: category },
    );
    setRows([
      {
        taxFilingId: res.taxFilingId,
        submissionYear: year,
        incomeCategory: category,
        totalAmount: res.totalAmount,
        fileName: '',
      },
      ...rows,
    ]);
    setCreating(false);
    setYear('');
    setCategory('');
    notify('제출집계표를 작성했습니다.');
  };

  const generate = async () => {
    if (!target) {
      return;
    }
    const res = await call<{ fileName: string }>(
      'POST',
      '/tax-filings/' + target.taxFilingId + '/generate-media',
      role,
    );
    setRows(
      rows.map((r) => (r.taxFilingId === target.taxFilingId ? { ...r, fileName: res.fileName } : r)),
    );
    setTarget(null);
    notify('지급명세서 전산매체 파일을 생성했습니다.');
  };

  return (
    <div className="doc">
      <section className="box">
        <h2>소득자료 제출집계표</h2>
        <Band total={rows.length}>
          <button onClick={() => setCreating(true)}>제출집계표 작성</button>
        </Band>
        <DataTable<Summary>
          columns={[
            { key: 'taxFilingId', label: '제출집계표 번호' },
            { key: 'submissionYear', label: '제출 대상 연도' },
            { key: 'incomeCategory', label: '소득 구분', render: (r) => <span>{categoryName(r.incomeCategory)}</span> },
            { key: 'totalAmount', label: '집계 금액', render: (r) => <Num value={r.totalAmount} /> },
            {
              key: 'fileName',
              label: '전산매체 파일',
              render: (r) =>
                r.fileName ? (
                  <span>{r.fileName}</span>
                ) : (
                  <button className="ghost" onClick={() => setTarget(r)}>
                    파일 생성
                  </button>
                ),
            },
          ]}
          rows={rows}
          empty="아직 작성한 제출집계표가 없습니다. 제출집계표 작성 버튼을 눌러 시작해 주세요."
        />
      </section>
      {creating && (
        <Drawer title="제출집계표 작성" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="작성">
            <Field label="제출 대상 연도" required hint="예: 2024">
              <TextInput value={year} onChange={setYear} placeholder="YYYY" />
            </Field>
            <Field label="소득 구분" required>
              <Select value={category} onChange={setCategory} options={CATEGORY_OPTIONS} />
            </Field>
          </Form>
        </Drawer>
      )}
      {target && (
        <Drawer title="지급명세서 전산매체 파일 생성" onClose={() => setTarget(null)}>
          <Form
            onSubmit={generate}
            submit="파일 생성"
            note={
              <span>
                {target.submissionYear}년 {categoryName(target.incomeCategory)} 집계표(번호 {target.taxFilingId})로 국세청 제출 규격 파일을 생성합니다. 규격 검증에 실패하면 파일 생성을 중단하고 사유를 알려 드립니다.
              </span>
            }
          />
        </Drawer>
      )}
    </div>
  );
}
